// 1. 버튼 클릭 이벤트 핸들러 안에서
button.onClick = () => {
  setCount(1)  // → SyncLane (클릭 이벤트 안이라서)
}

// 2. fetch 완료 후 콜백 안에서
fetch('/api/data').then(data => {
  setCount(data.count)  // → DefaultLane (네트워크 콜백 안이라서)
})

// 3. useTransition 안에서
startTransition(() => {
  setCount(3)  // → TransitionLane (개발자가 표시)
})

