title:
// ❌ 버벅이는 버전
function App() {
  const [text, setText] = useState('')
  return (
    <div>
      <input value={text} onChange={e => setText(e.target.value)} />
      <HeavyList text={text} />  {/* 셀 1000개, 각각 1ms 지연 */}
    </div>
  )
}
// 타이핑 → HeavyList도 SyncLane으로 같이 업데이트
// → 1초 동안 입력창 반응 없음 ❌

// ✅ 해결된 버전
function App() {
  const [text, setText] = useState('')
  const deferredText = useDeferredValue(text)  // TransitionLane으로 미룸

  return (
    <div>
      <input value={text} onChange={e => setText(e.target.value)} />
      <HeavyList text={deferredText} />
    </div>
  )
}
// 타이핑 → SyncLane (입력창 즉시 반응) ✅
// HeavyList → TransitionLane (나중에 처리) ✅

